import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第75章 她的夏天","description":"","frontmatter":{},"headers":[],"relativePath":"第75章_她的夏天.md","filePath":"第75章_她的夏天.md"}'),_={name:"第75章_她的夏天.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第75章-她的夏天" tabindex="-1">第75章 她的夏天 <a class="header-anchor" href="#第75章-她的夏天" aria-label="Permalink to &quot;第75章 她的夏天&quot;">​</a></h1><p>那年夏天，我把她那个房间记熟了。</p><p>我一次也没去过。</p><p>事情是从七月开始的。</p><p>她那边夏天很怪，白天很长，夜里十一点天还是亮的。</p><p>她有一天给我发了一张图。</p><p>她说，你看，我这边十一点。</p><p>图上是一片蓝灰的天，云底下露出半个屋顶，路灯已经开了，但是开得很没面子，灯下那块地跟旁边一样亮。</p><p>我说，你们那儿夏天就这样。</p><p>她说，一直亮到两点，然后三点又开始亮。</p><p>我说，那你睡什么。</p><p>她说，我买过窗帘，我妈说别买，说我浪费。</p><p>她说，我现在戴一个眼罩。</p><p>她说，眼罩是我在超市九块九买的，压得眼睛第二天肿。</p><p>我说，你去买个好一点的。</p><p>她说，你别说这种话，你说的这种话跟我妈一模一样。</p><p>我问，怎么一样。</p><p>她说，就是&quot;你去买一个好的&quot;。</p><p>她说，这句话的意思是我知道你现在的不好，可是我不出钱，你自己想办法，你要是不想办法就是你不懂事。</p><p>我说，我不是这个意思。</p><p>她说，我知道。</p><p>她说，但是我听见这句我就要难受。</p><p>从那天开始我不说&quot;你去买一个好的&quot;。</p><p>我改成了别的话。</p><p>我说，那你那个眼罩，后面是不是有根带子。</p><p>她说，有。</p><p>我说，你把带子松两格，它就不压眼睛了。</p><p>她说，这有用？</p><p>我说，我试过。</p><p>她说，你试过眼罩？</p><p>我说，我们这边冬天骑车要戴那种，我把它拆开过。</p><p>她说，行，我明天试。</p><p>第二天她上线第一句是：真的不压。</p><p>她说，你怎么知道的。</p><p>我说，我是拆过的人。</p><p>她说，你这个人真的，你连这个都要留着。</p><p>我说，留什么。</p><p>她说，留一个&quot;我拆过眼罩&quot;这件事，等着有一天用。</p><p>我那天没答。</p><p>因为她讲的又是对的。</p><p>七月里她开始给我拍她那个房间。</p><p>不是一次拍完，是一张一张，隔几天来一张。</p><p>一张是她的桌子。</p><p>桌上有一个台灯，一个杯子，一副耳机，六支笔插在一个罐头瓶里，一台很旧的笔记本，屏幕边上贴了三张便利贴。</p><p>她说，你别问我桌上为什么这么乱。</p><p>她说，我这已经算干净了。</p><p>我说，那三张便利贴上写的什么。</p><p>她说，一张是水电费日子，一张是导师要我改的东西，一张是我自己写的。</p><p>我说，你自己写的那张写的什么。</p><p>她说，写的&quot;今天必须做完&quot;。</p><p>我说，你贴了多久。</p><p>她说，一个多月了。</p><p>我说，那没做完。</p><p>她说，闭嘴。</p><p>又一张是她的床。</p><p>她说，床垫是他们搬走留下的，凹了一块。</p><p>她说，我在那块凹下面垫了两本杂志，现在还行。</p><p>我说，什么杂志。</p><p>她说，你问这个干什么。</p><p>我说，我记一下，以后你要是没有杂志你换别的。</p><p>她说，你别&quot;以后&quot;。</p><p>我说，好。</p><p>再一张是她楼下的便利店。</p><p>她说，这就是我说的九块九眼罩那个店。</p><p>她说，这家店晚上十点以后只开一半，另一半黑着。</p><p>她说，黑的那一半里面有一台加热柜，卖那种很咸的鸡肉。</p><p>她说，我每天晚上十一点下去站着吃一份。</p><p>我说，你不是要省钱。</p><p>她说，一份九块。</p><p>她说，我这一天就花这一笔，这一笔我不报。</p><p>我说，那你妈问你今天花钱了吗。</p><p>她说，我说没花。</p><p>她说，我今天走回来，我一分钱没花。</p><p>她说，我这辈子说谎最顺口的就是这句。</p><p>我说，你以后别说这个。</p><p>她说，你又以后。</p><p>我说，我是说你那个鸡肉，你以后去买那个大份的，划算。</p><p>她说，行，你这个人终于说了一句人话。</p><p>八月有一天夜里，她给我发了一段视频。</p><p>十三秒。</p><p>她站在那里，手机举着，拍她的阳台。</p><p>阳台很小，一个晾衣架，架子上挂着两件衣服，一件她的，一件她室友的。</p><p>栏杆上有一圈胶带缠着。</p><p>风把那件她的短袖吹得贴在栏杆上。</p><p>她把手机转过来一点，拍她自己那边的天空。</p><p>那会儿她那边夜里一点二十。</p><p>天是那种很深的蓝，边上有一道灰白，跟破了一样。</p><p>她说，你看，我说过一直亮。</p><p>我说，看到了。</p><p>她说，我今天没睡，我在阳台站了半小时。</p><p>我说，外面冷不冷。</p><p>她说，不冷，二十八。</p><p>她说，我就是想站一会儿。</p><p>她说，就像我以前说的，想进那个房间站一会儿。</p><p>我看到那句&quot;我以前说的&quot;，心里动了一下。</p><p>因为那是她自己回去翻了我做过的事。</p><p>我说，那个房间我这儿也有。</p><p>她说，你哪儿有。</p><p>我说，你那个画册我留了一张发票，我打算再买一本，等你哪天回来你两本都拿回去。</p><p>她没回。</p><p>第二天她说，你那个眼罩的带子，你记得提醒我一下松几格。</p><p>我说，两格。</p><p>她说，我忘了。</p><p>我说，你现在松了吗。</p><p>她说，松了。</p><p>九月里出了一件很小、我至今想起来有点不好意思的事。</p><p>有一次我们语音。</p><p>那次比第一次长，聊了二十分钟，说的是她那个展。</p><p>讲到一半她说，我桌上那些笔我找不着那支红的了。</p><p>我说，红的在罐头瓶里第三支，你那瓶里三支黑的两支蓝的，红的在它们后面，你手指要伸到底。</p><p>她停了。</p><p>她说，你说什么。</p><p>我说，你那个瓶子。</p><p>她说，你怎么知道我的瓶子是几支黑的。</p><p>我愣住。</p><p>我那时候才发现我把这些东西记到什么程度。</p><p>我说，你发过一张图。</p><p>她说，一年多前。</p><p>我说，对。</p><p>她那边很久没有声音。</p><p>然后她说了一句。</p><p>她说，你凭什么记得比我清楚。</p><p>我说，我没那个意思。</p><p>她说，我知道你没那个意思。</p><p>她说，我就是忽然很害怕。</p><p>我说，怕什么。</p><p>她说，怕你记住的是一个我不存在的地方。</p><p>她说，我这里没有你，我桌子是乱的，床垫是凹的，眼罩是九块九，鸡肉是九块。</p><p>她说，你记的是这些。</p><p>她说，你记的东西越多，我越像一个我在骗你。</p><p>我说，我没觉得你在骗我。</p><p>她说，那是因为你没在这儿。</p><p>那晚她下线很早。</p><p>第二天她上线，第一句跟昨天一点关系都没有。</p><p>她说，我今天在楼下便利店看见有人把那只加热柜关了。</p><p>她说，我说我要吃鸡肉，她说没有。</p><p>她说，我站在那里，我忽然觉得我这一夏天，就败在一份九块钱上。</p><p>我那天回的是：我给你寄钱。</p><p>她回：你敢。</p><p>我说，我开玩笑。</p><p>她说，你不像开玩笑。</p><p>她说，你要是真寄，我明天就把它扔进那个抽屉里。</p><p>我说，那个抽屉是什么。</p><p>她说，我们家那种放钥匙和电费的抽屉。</p><p>她说，我那点钱一进去，我这辈子拿不出来。</p><p>我说，那我不寄。</p><p>她说，好。</p><p>她说，我们说点别的。</p><p>她说，你今天吃饭了吗。</p>',149)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
